package dev.pathland.view;

import java.util.Collection;

/**
 * The mutable collector passed to a block-form {@code children(...)} call
 * (spec DSL.md §2). It is the same {@code children} operation as the varargs
 * form, spelled as a block so each structural element has a brace-delimited
 * body the IDE can fold and indent:
 *
 * <pre>{@code
 * VStack.make(v -> v.spacing(8)).children(content -> {
 *     content.add(Text.make("a"));
 *     content.add(HStack.make().children(row -> {
 *         row.add(Text.make("b"));
 *         row.add(Spacer.make());
 *     }));
 * });
 * }</pre>
 *
 * <p>Children are appended in call order; the collected views pass through the
 * same {@link ViewBuilder#children(View...)} path as the varargs form, so the
 * two forms emit byte-identical opcodes.
 */
@FunctionalInterface
public interface ChildScope {

    /** Append one or more children in call order. */
    void add(View... children);

    /** Append every view in {@code children} in iteration order. */
    default void addAll(Collection<? extends View> children) {
        add(children.toArray(new View[0]));
    }
}

