/**
 * Supply the content from a block (spec DSL.md §2) — the same {@code children}
 * operation as {@link #children(View...)}, with each
 * {@link ChildScope#add(View...)} appended in call order. Pure sugar: the
 * collected children take the same path, so both forms emit byte-identical
 * opcodes.
 */
public ViewBuilder<V, C> children(Consumer<ChildScope> content) {
    ChildScope scope = this::children;
    content.accept(scope);
    return this;
}

