package dev.pathland.view;

import java.util.Collection;

/**
 * The mutable collector passed to a block-form {@link SizeThatFits#make} call
 * (spec DSL.md §4.2). Candidates are appended in call order; the collected
 * {@link Fit}s are sorted by threshold for the wire `FIT_QUERY` table, so the
 * authoring order is not significant.
 *
 * <pre>{@code
 * SizeThatFits.make(fits -> {
 *     fits.add(wideLayout, 640f);   // shown when the slot is ≥ 640 wide
 *     fits.add(compactLayout);      // minWidth 0 — the always-valid fallback
 * });
 * }</pre>
 */
@FunctionalInterface
public interface FitScope {

    /** Append a width-keyed candidate. */
    void add(Fit fit);

    /** Append a candidate with threshold 0 (the fallback). */
    default void add(View view) {
        add(Fit.of(view));
    }

    /** Append a candidate shown when the slot is at least {@code minWidth} wide. */
    default void add(View view, float minWidth) {
        add(Fit.of(view, minWidth));
    }

    /** Append every candidate in iteration order. */
    default void addAll(Collection<? extends Fit> fits) {
        for (Fit fit : fits) {
            add(fit);
        }
    }
}

