    state = "code"  # code | line | block | string | char
    while i < n:
        c = s[i]
        if state == "code":
            if c == "/" and i + 1 < n and s[i + 1] == "/":
                state = "line"
                i += 2
                continue
            if c == "/" and i + 1 < n and s[i + 1] == "*":
                state = "block"
                i += 2
                continue
            if c == '"':
                state = "string"
                i += 1
                continue
            if c == "'":
                state = "char"
                i += 1
                continue
            yield i, c
            i += 1
        elif state == "line":
            if c == "\n":
                state = "code"
            i += 1
        elif state == "block":
            if c == "*" and i + 1 < n and s[i + 1] == "/":
                state = "code"
                i += 2
            else:
                i += 1
        elif state == "string":
            if c == "\\":
                i += 2
            elif c == '"':
                state = "code"
                i += 1
            else:
                i += 1
        elif state == "char":
            if c == "\\":
                i += 2
            elif c == "'":
                state = "code"
                i += 1
            else:
                i += 1


def find_marker(s, marker):
    out = []
    for i, _ in scan_code(s):
        if s.startswith(marker, i):
            out.append(i)
    return out


def find_matching_paren(s, open_idx):
    depth = 0
    i = open_idx
    n = len(s)
    state = "code"
    while i < n:
        c = s[i]
        if state == "code":
            if c == "/" and i + 1 < n and s[i + 1] == "/":
                state = "line"; i += 2; continue
            if c == "/" and i + 1 < n and s[i + 1] == "*":
                state = "block"; i += 2; continue
            if c == '"':
                state = "string"; i += 1; continue
            if c == "'":
                state = "char"; i += 1; continue
            if c == "(":
                depth += 1
            elif c == ")":
                depth -= 1
                if depth == 0:
                    return i
            i += 1
        elif state == "line":
            if c == "\n": state = "code"
            i += 1
        elif state == "block":
            if c == "*" and i + 1 < n and s[i + 1] == "/":
                state = "code"; i += 2
            else:
                i += 1
        elif state == "string":
            if c == "\\": i += 2
            elif c == '"': state = "code"; i += 1
            else: i += 1
        elif state == "char":
            if c == "\\": i += 2
            elif c == "'": state = "code"; i += 1
            else: i += 1
    raise ValueError("unmatched paren")


def split_top_level(content):
    parts = []
    depth = 0
    i = 0
    n = len(content)
    start = 0
    state = "code"
    while i < n:
        c = content[i]
        if state == "code":
            if c == "/" and i + 1 < n and content[i + 1] == "/":
                state = "line"; i += 2; continue
            if c == "/" and i + 1 < n and content[i + 1] == "*":
                state = "block"; i += 2; continue
            if c == '"':
                state = "string"; i += 1; continue
            if c == "'":
                state = "char"; i += 1; continue
            if c in "([{":
                depth += 1
            elif c in ")]}":
                depth -= 1
            elif c == "," and depth == 0:
                parts.append(content[start:i])
                start = i + 1
            i += 1
        elif state == "line":
            if c == "\n": state = "code"
            i += 1
        elif state == "block":
            if c == "*" and i + 1 < n and content[i + 1] == "/":
                state = "code"; i += 2
            else:
                i += 1
        elif state == "string":
            if c == "\\": i += 2
            elif c == '"': state = "code"; i += 1
            else: i += 1
        elif state == "char":
            if c == "\\": i += 2
            elif c == "'": state = "code"; i += 1
            else: i += 1
    parts.append(content[start:])
    return [p.strip() for p in parts if p.strip()]


def line_indent(s, pos):
    ls = s.rfind("\n", 0, pos) + 1
    m = re.match(r"[ \t]*", s[ls:])
    return m.group(0) if m else ""


def is_block_lambda(content):
    return re.match(r"^\s*\(?\s*[A-Za-z_]\w*\s*\)?\s*->", content) is not None


def nesting_depth(calls, pos):
    return sum(1 for (st, _op, cl) in calls if st < pos < cl)


def parse_fit_of(arg):
    if arg.startswith("Fit.of(") and arg.endswith(")"):
        inner = arg[len("Fit.of("):-1]
        parts = split_top_level(inner)
        if len(parts) == 1:
            return f".add({parts[0]})"
        if len(parts) == 2:
            return f".add({parts[0]}, {parts[1]})"
    return f".add({arg})"


def rewrite_file(path):
    s = path.read_text()
    original = s
    children_calls = []
    for st in find_marker(s, CHILDREN):
        op = st + len(CHILDREN) - 1
        try:
            cl = find_matching_paren(s, op)
        except ValueError:
            continue
        children_calls.append((st, op, cl))
    stf_calls = []
    for st in find_marker(s, STF):
        op = st + len(STF) - 1
        try:
            cl = find_matching_paren(s, op)
        except ValueError:
            continue
        stf_calls.append((st, op, cl))

    calls = [("child", st, op, cl) for (st, op, cl) in children_calls] + \
            [("fit", st, op, cl) for (st, op, cl) in stf_calls]
    calls.sort(key=lambda x: x[1], reverse=True)

    changed = False
    for kind, st, _op, _cl in calls:
        marker = CHILDREN if kind == "child" else STF
        op = st + len(marker) - 1
        try:
            cl = find_matching_paren(s, op)
        except ValueError:
            continue
        content = s[op + 1:cl]
        if not content.strip():
            if kind == "child" and re.search(r"Group\s*$", s[:st]):
                s = s[:st] + ".make()" + s[cl + 1:]
                changed = True
            continue
        if is_block_lambda(content):
            continue
        args = split_top_level(content)
        if not args:
            continue
        base = line_indent(s, st)
        inner = base + "    "
        if kind == "child":
            depth = nesting_depth(children_calls, st)
            scope = "childScope" + (str(depth) if depth else "")
            lines = [inner + f"{scope}.add({a});" for a in args]
            repl = f".children({scope} -> {{\n" + "\n".join(lines) + "\n" + base + "})"
        else:
            depth = nesting_depth(stf_calls, st)
            scope = "fitScope" + (str(depth) if depth else "")
            lines = []
            for a in args:
                call = parse_fit_of(a)
                lines.append(inner + scope + call + ";")
            repl = f"SizeThatFits.make({scope} -> {{\n" + "\n".join(lines) + "\n" + base + "})"
        s = s[:st] + repl + s[cl + 1:]
        changed = True

    if changed and s != original:
        path.write_text(s)
        return True
    return False


def main(roots):
    files = []
    for root in roots:
        files.extend(Path(root).rglob("*.java"))
    files = [f for f in files if "/target/" not in str(f)]
    count = 0
    for f in files:
        try:
            if rewrite_file(f):
                count += 1
                print("rewrote", f)
        except Exception as e:
            print("ERROR", f, e, file=sys.stderr)
    print("files changed:", count)


if __name__ == "__main__":
    main(sys.argv[1:])

