package dev.pathland.view;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import dev.pathland.view.emit.PathlandNode;
import org.junit.jupiter.api.Test;

import java.util.List;

import static dev.pathland.view.Modifiers.*;

/** The v2 authoring surface: {@code make} / {@code modifiers} / {@code children}. */
public class ViewBuilderTest {

    @Test
    void makeConfiguresText() {
        PathlandNode node = Text.make(t -> t.text("hi")).render(Environment.DEFAULT);
        assertEquals("hi", node.text);
    }

    @Test
    void modifiersAndChildrenMayBeUsedInAnyOrder() {
        View a = VStack.make(v -> v.spacing(8)).children(childScope -> {
            childScope.add(Text.make(t -> t.text("a")));
        })
                .modifiers(padding(p -> p.uniform(4)));
        View b = VStack.make(v -> v.spacing(8))
                .modifiers(padding(p -> p.uniform(4))).children(childScope -> {
                    childScope.add(Text.make(t -> t.text("a")));
                });

        PathlandNode na = a.render(Environment.DEFAULT);
        PathlandNode nb = b.render(Environment.DEFAULT);

        assertEquals(8f, na.properties.get(Properties.SPACING));
        assertEquals(na.properties.get(Properties.SPACING), nb.properties.get(Properties.SPACING));
        assertEquals(4f, na.properties.get(Properties.PADDING));
        assertEquals(1, na.children.size());
        assertEquals(1, nb.children.size());
    }

    @Test
    void makeStartsTheChain() {
        PathlandNode node =
                VStack.make().modifiers(padding(p -> p.uniform(16)))
                        .children(childScope -> {
                            childScope.add(Text.make(t -> t.text("x")));
                        }).render(Environment.DEFAULT);
        assertEquals(16f, node.properties.get(Properties.PADDING));
        assertTrue(node.children.size() == 1);
    }

    @Test
    void blockChildrenEqualVarargs() {
        View varargs = VStack.make(v -> v.spacing(8))
                .children(childScope -> {
                    childScope.add(Text.make("a"));
                    childScope.add(Text.make("b"));
                });
        View block = VStack.make(v -> v.spacing(8))
                .children(content -> {
                    content.add(Text.make("a"));
                    content.add(Text.make("b"));
                });

        assertSameTree(varargs.render(Environment.DEFAULT), block.render(Environment.DEFAULT));
    }

    @Test
    void nestedBlockChildrenBuildTheSameTree() {
        View varargs = VStack.make().children(childScope -> {
            childScope.add(Text.make("a"));
            childScope.add(HStack.make(h -> h.spacing(4)).children(childScope1 -> {
                    childScope1.add(Text.make("b"));
                    childScope1.add(Spacer.make());
                }));
        });
        View block = VStack.make().children(content -> {
            content.add(Text.make("a"));
            content.add(HStack.make(h -> h.spacing(4)).children(row -> {
                row.add(Text.make("b"));
                row.add(Spacer.make());
            }));
        });

        assertSameTree(varargs.render(Environment.DEFAULT), block.render(Environment.DEFAULT));
    }

    @Test
    void blockChildrenAddAllAppendsInOrder() {
        PathlandNode node = VStack.make().children(content -> {
            content.add(Text.make("a"));
            content.addAll(List.of(Text.make("b"), Text.make("c")));
        }).render(Environment.DEFAULT);

        assertEquals(3, node.children.size());
        assertEquals("a", node.children.get(0).text);
        assertEquals("b", node.children.get(1).text);
        assertEquals("c", node.children.get(2).text);
    }

    @Test
    void staticBlockChildrenStartsTheChain() {
        PathlandNode node = VStack.children(content -> {
            content.add(Text.make("x"));
        }).render(Environment.DEFAULT);

        assertEquals(1, node.children.size());
        assertEquals("x", node.children.get(0).text);
    }

    @Test
    void blockChildrenAndModifiersMayBeUsedInAnyOrder() {
        View before = VStack.make(v -> v.spacing(8))
                .modifiers(padding(4))
                .children(content -> content.add(Text.make("a")));
        View after = VStack.make(v -> v.spacing(8))
                .children(content -> content.add(Text.make("a")))
                .modifiers(padding(4));

        assertSameTree(before.render(Environment.DEFAULT), after.render(Environment.DEFAULT));
    }

    private static void assertSameTree(PathlandNode expected, PathlandNode actual) {
        assertEquals(expected.component, actual.component);
        assertEquals(expected.text, actual.text);
        assertEquals(expected.properties, actual.properties);
        assertEquals(expected.children.size(), actual.children.size());
        for (int i = 0; i < expected.children.size(); i++) {
            assertSameTree(expected.children.get(i), actual.children.get(i));
        }
    }
}

