#!/usr/bin/env python3
import re
import sys
from pathlib import Path

CHILDREN = ".children("
STF = "SizeThatFits.make("


def scan(s):
    """Yield positions outside strings/comments."""
    i, n = 0, len(s)
    state = "code"
    while i < n:
        c = s[i]
        if state == "code":
            if c == "/" and i + 1 < n and s[i + 1] == "/":
                state = "line"; i += 2; continue
            if c == "/" and i + 1 < n and s[i + 1] == "*":
                state = "block"; i += 2; continue
            if c == '"': state = "string"; i += 1; continue
            if c == "'": state = "char"; i += 1; continue
            yield i, c; i += 1
        elif state == "line":
            if c == "\n": state = "code"
            i += 1
        elif state == "block":
            if c == "*" and i + 1 < n and s[i + 1] == "/": state = "code"; i += 2
            else: i += 1
        elif state == "string":
            if c == "\\": i += 2
            elif c == '"': state = "code"; i += 1
            else: i += 1
        elif state == "char":
            if c == "\\": i += 2
            elif c == "'": state = "code"; i += 1
            else: i += 1


def find_marker(s, marker):
    return [i for i, _ in scan(s) if s.startswith(marker, i)]


def matching(s, open_idx, open_ch="(", close_ch=")"):
    depth = 0
    i, n = open_idx, len(s)
    state = "code"
    while i < n:
        c = s[i]
        if state == "code":
            if c == "/" and i + 1 < n and s[i + 1] == "/": state = "line"; i += 2; continue
            if c == "/" and i + 1 < n and s[i + 1] == "*": state = "block"; i += 2; continue
            if c == '"': state = "string"; i += 1; continue
            if c == "'": state = "char"; i += 1; continue
            if c == open_ch: depth += 1
            elif c == close_ch:
                depth -= 1
                if depth == 0: return i
            i += 1
        elif state == "line":
            if c == "\n": state = "code"
            i += 1
        elif state == "block":
            if c == "*" and i + 1 < n and s[i + 1] == "/": state = "code"; i += 2
            else: i += 1
        elif state == "string":
            if c == "\\": i += 2
            elif c == '"': state = "code"; i += 1
            else: i += 1
        elif state == "char":
            if c == "\\": i += 2
            elif c == "'": state = "code"; i += 1
            else: i += 1
    raise ValueError("unmatched")


def line_indent(s, pos):
    ls = s.rfind("\n", 0, pos) + 1
    m = re.match(r"[ \t]*", s[ls:])
    return m.group(0)


def split_statements(body):
    out = []
    depth = 0
    start = 0
    i, n = 0, len(body)
    state = "code"
    while i < n:
        c = body[i]
        if state == "code":
            if c == "/" and i + 1 < n and body[i + 1] == "/": state = "line"; i += 2; continue
            if c == "/" and i + 1 < n and body[i + 1] == "*": state = "block"; i += 2; continue
            if c == '"': state = "string"; i += 1; continue
            if c == "'": state = "char"; i += 1; continue
            if c in "([{": depth += 1
            elif c in ")]}": depth -= 1
            elif c == ";" and depth == 0:
                out.append(body[start:i]); start = i + 1
            i += 1
        elif state == "line":
            if c == "\n": state = "code"
            i += 1
        elif state == "block":
            if c == "*" and i + 1 < n and body[i + 1] == "/": state = "code"; i += 2
            else: i += 1
        elif state == "string":
            if c == "\\": i += 2
            elif c == '"': state = "code"; i += 1
            else: i += 1
        elif state == "char":
            if c == "\\": i += 2
            elif c == "'": state = "code"; i += 1
            else: i += 1
    out.append(body[start:])
    return out


def find_scope_call(stmt, scope):
    marker = scope + "."
    for i, _ in scan(stmt):
        if stmt.startswith(marker, i):
            # scope.add( or scope.addAll(
            rest = stmt[i + len(marker):]
            m = re.match(r"(addAll|add)\s*\(", rest)
            if m:
                return i, m.group(1), i + len(marker) + m.end() - 1
    return None


def reindent(arg, stmt_indent, inner):
    arg = arg.strip()
    if "\n" not in arg:
        return arg
    lines = arg.splitlines()
    out = [lines[0].strip()]
    delta = len(inner) - len(stmt_indent)
    for line in lines[1:]:
        if line.startswith(stmt_indent):
            out.append(inner + line[len(stmt_indent):])
        else:
            if delta >= 0:
                out.append(" " * delta + line)
            else:
                remove = min(-delta, len(line) - len(line.lstrip(" ")))
                out.append(line[remove:])
    return "\n".join(out)


def parse_children_lambda(content, s, start, kind):
    """Return ('array', elements) / ('direct', expr) / None."""
    m = re.match(r"\s*([A-Za-z_]\w*)\s*->\s*(.*)$", content, re.S)
    if not m:
        return None
    scope, body = m.group(1), m.group(2).strip()
    if body.startswith("{"):
        end = matching(body, 0, "{", "}")
        inner_body = body[1:end]
        trailing = body[end + 1:].strip()
        if trailing:
            return None
        elements = []
        for stmt in split_statements(inner_body):
            if not stmt.strip():
                continue
            found = find_scope_call(stmt, scope)
            if not found:
                # allow pure comments/whitespace
                if all(not line.strip() or line.strip().startswith("//") or line.strip().startswith("/*") or line.strip().startswith("*")
                       for line in stmt.splitlines()):
                    continue
                return None
            call_pos, method, open_idx = found
            close = matching(stmt, open_idx)
            arg = stmt[open_idx + 1:close]
            rest = stmt[close + 1:].strip()
            if rest:
                return None
            leading = stmt[:call_pos]
            if method == "addAll":
                return ("addall", arg.strip(), leading.strip(), len(elements) == 0)
            elements.append({
                "arg": arg,
                "leading": leading,
                "stmt_indent": line_indent(s, start + (s[start:].find(stmt)) if False else start),
            })
        if not elements:
            return ("array", [])
        return ("array", elements)
    else:
        # expression lambda: scope.add(...) / scope.addAll(...)
        found = find_scope_call(body, scope)
        if not found:
            return None
        call_pos, method, open_idx = found
        close = matching(body, open_idx)
        if body[close + 1:].strip():
            return None
        arg = body[open_idx + 1:close].strip()
        return ("addall" if method == "addAll" else "single", arg, "", True)
    return None


def render_array(elements, base, type_name):
    inner = base + "    "
    if not elements:
        return f".children(new {type_name}[] {{}})"
    lines = []
    for idx, el in enumerate(elements):
        leading = el.get("leading", "").strip()
        if leading:
            for line in leading.splitlines():
                if line.strip():
                    lines.append(inner + line.strip())
        arg = reindent(el["arg"], el.get("stmt_indent", base), inner)
        arg_lines = arg.splitlines()
        for i in range(len(arg_lines)):
            if i == 0:
                arg_lines[i] = inner + arg_lines[i].lstrip()
            # subsequent lines already reindented
        if idx < len(elements) - 1:
            arg_lines[-1] += ","
        lines.extend(arg_lines)
    return f".children(new {type_name}[] {{\n" + "\n".join(lines) + "\n" + base + "})"


def rewrite_file(path):
    s = path.read_text()
    original = s
    calls = []
    for st in find_marker(s, CHILDREN):
        op = st + len(CHILDREN) - 1
        try:
            cl = matching(s, op)
        except ValueError:
            continue
        calls.append(("children", st, op, cl))
    for st in find_marker(s, STF):
        op = st + len(STF) - 1
        try:
            cl = matching(s, op)
        except ValueError:
            continue
        calls.append(("fit", st, op, cl))
    calls.sort(key=lambda x: x[1], reverse=True)

    changed = False
    unsupported = []
    for kind, st, _, _ in calls:
        marker = CHILDREN if kind == "children" else STF
        op = st + len(marker) - 1
        try:
            cl = matching(s, op)
        except ValueError:
            continue
        content = s[op + 1:cl]
        stripped = content.strip()
        if not stripped:
            continue
        if stripped.startswith("new View[]") or stripped.startswith("new Fit[]"):
            continue
        # already migrated array variable / other expression: no arrow at top level
        parsed = parse_children_lambda(content, s, st, kind)
        if parsed is None:
            # Skip non-lambda expressions (already array/variable) silently,
            # report lambda-looking ones as unsupported.
            if "->" in stripped:
                unsupported.append((path, st, stripped[:80]))
            continue
        base = line_indent(s, st)
        if parsed[0] == "array":
            repl = render_array(parsed[1], base, "View" if kind == "children" else "Fit")
        elif parsed[0] == "single":
            repl = render_array([{"arg": parsed[1], "leading": "", "stmt_indent": base}], base, "View")
        elif parsed[0] == "addall":
            _, arg, leading, only = parsed
            if not only:
                unsupported.append((path, st, "addAll mixed with add"))
                continue
            repl = f".children({arg}.toArray(new View[0]))"
        else:
            unsupported.append((path, st, "unknown"))
            continue
        s = s[:st] + repl + s[cl + 1:]
        changed = True
    if changed and s != original:
        path.write_text(s)
        return True, unsupported
    return False, unsupported


def main(args):
    roots = [Path(a) for a in args]
    files = []
    for root in roots:
        if root.is_file():
            files.append(root)
        else:
            files.extend(root.rglob("*.java"))
    files = sorted(set(f for f in files if "/target/" not in str(f)))
    changed = 0
    all_unsupported = []
    for f in files:
        try:
            did, uns = rewrite_file(f)
            if did:
                changed += 1
                print("rewrote", f)
            all_unsupported.extend(uns)
        except Exception as e:
            all_unsupported.append((f, 0, f"ERROR {e}"))
    print("files changed:", changed)
    if all_unsupported:
        print("--- unsupported ---")
        for u in all_unsupported:
            print(u)


if __name__ == "__main__":
    main(sys.argv[1:])

